describe('Async Error Retry Functionality', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
    cy.intercept('GET', '/api/data', { delay: 100 }).as('getData');
  });

  it('should display retry option when async operation fails', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('failedRequest');

    cy.get('[data-testid="load-data-btn"]').click();
    cy.wait('@failedRequest');

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Something went wrong');

    cy.get('[data-testid="retry-btn"]').should('be.visible');
    cy.get('[data-testid="retry-btn"]').should('not.be.disabled');
  });

  it('should successfully retry and load data after async error', () => {
    let requestCount = 0;

    cy.intercept('GET', '/api/data', (req) => {
      requestCount++;
      if (requestCount === 1) {
        req.reply({
          statusCode: 500,
          body: { error: 'Server error' }
        });
      } else {
        req.reply({
          statusCode: 200,
          body: { data: 'Success data' }
        });
      }
    }).as('dataRequest');

    cy.get('[data-testid="load-data-btn"]').click();
    cy.wait('@dataRequest');

    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="retry-btn"]').click();

    cy.wait('@dataRequest');
    cy.get('[data-testid="error-message"]').should('not.exist');
    cy.get('[data-testid="data-content"]').should('be.visible');
    cy.get('[data-testid="data-content"]').should('contain', 'Success data');
  });

  it('should disable retry button during retry attempt', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Server error' },
      delay: 2000
    }).as('slowRequest');

    cy.get('[data-testid="load-data-btn"]').click();
    cy.wait('@slowRequest');

    cy.get('[data-testid="retry-btn"]').click();
    cy.get('[data-testid="retry-btn"]').should('be.disabled');
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
  });

  it('should show retry count after multiple failures', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('failedRequest');

    cy.get('[data-testid="load-data-btn"]').click();
    cy.wait('@failedRequest');
    cy.get('[data-testid="retry-count"]').should('contain', 'Attempt 1');

    cy.get('[data-testid="retry-btn"]').click();
    cy.wait('@failedRequest');
    cy.get('[data-testid="retry-count"]').should('contain', 'Attempt 2');

    cy.get('[data-testid="retry-btn"]').click();
    cy.wait('@failedRequest');
    cy.get('[data-testid="retry-count"]').should('contain', 'Attempt 3');
  });

  it('should clear error message when user initiates new request', () => {
    cy.intercept('GET', '/api/data', {
      statusCode: 500,
      body: { error: 'Server error' }
    }).as('failedRequest');

    cy.get('[data-testid="load-data-btn"]').click();
    cy.wait('@failedRequest');
    cy.get('[data-testid="error-message"]').should('be.visible');

    cy.intercept('GET', '/api/data', {
      statusCode: 200,
      body: { data: 'New data' }
    }).as('successRequest');

    cy.get('[data-testid="load-data-btn"]').click();
    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('not.exist');

    cy.wait('@successRequest');
    cy.get('[data-testid="data-content"]').should('contain', 'New data');
  });
});
